private function generatePreventiveExcelNative($header, $details, $spreadsheet, $filename)
{
    $sheet = $spreadsheet->getActiveSheet();

    // Font
    $spreadsheet->getDefaultStyle()->getFont()->setName('Arial')->setSize(10);

    // Columns A to AF
    $sheet->getColumnDimension('A')->setWidth(2);
    foreach (range('B', 'Z') as $col) {
        $sheet->getColumnDimension($col)->setWidth(4);
    }
    foreach (['AA','AB','AC','AD','AE','AF'] as $col) {
        $sheet->getColumnDimension($col)->setWidth(4);
    }

    $borderStyle = [
        'borders' => [
            'allBorders' => ['borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN, 'color' => ['argb' => 'FF000000']]
        ]
    ];

    // Logo
    $sheet->mergeCells("B2:G7");
    $logoPath = FCPATH . 'uploads/nsi_logo.png';
    if (file_exists($logoPath)) {
        $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
        $drawing->setName('Logo NSI');
        $drawing->setPath($logoPath);
        $drawing->setCoordinates('B2');
        $drawing->setHeight(100);
        $drawing->setOffsetX(5);
        $drawing->setOffsetY(5);
        $drawing->setWorksheet($sheet);
    }

    // Title
    $sheet->mergeCells("H2:AF5");
    $title = "CHECKLIST REPORT - " . strtoupper($header['kategori'] ?? 'MESIN CNC') . " (" . strtoupper($header['departemen_check'] ?? '-') . ")";
    $sheet->setCellValue('H2', $title);
    $sheet->getStyle("H2")->getFill()->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)->getStartColor()->setARGB('FF92B0D6');
    $sheet->getStyle("H2")->getFont()->setBold(true)->setSize(12);
    $sheet->getStyle("H2")->getAlignment()->setHorizontal('center')->setVertical('center');

    // NO. DOCUMENT, REVISI, HALAMAN
    $sheet->mergeCells("H6:S6"); $sheet->setCellValue('H6', 'NO. DOCUMENT');
    $sheet->mergeCells("T6:Y6"); $sheet->setCellValue('T6', 'NO REVISI');
    $sheet->mergeCells("Z6:AF6"); $sheet->setCellValue('Z6', 'HALAMAN');
    $sheet->getStyle("H6:AF6")->getAlignment()->setHorizontal('center')->setVertical('center');

    $sheet->mergeCells("H7:S7"); $sheet->setCellValue('H7', 'FM-MTN-10');
    $sheet->mergeCells("T7:Y7"); $sheet->setCellValue('T7', '0');
    $sheet->mergeCells("Z7:AF7"); $sheet->setCellValue('Z7', '1 dari 1');
    $sheet->getStyle("H7:AF7")->getAlignment()->setHorizontal('center')->setVertical('center')->setBold(true);

    $sheet->mergeCells("B8:AF8");
    $sheet->setCellValue('B8', 'Rev.:0/291124');

    $sheet->getStyle("B2:AF8")->applyFromArray($borderStyle);

    // PIC, Date, Machine Info
    $rawNamaTop = $header['nama_pic'] ?: ($header['nama_staff'] ?? 'MEMBER');
    $namaTopParts = explode(' - ', $rawNamaTop);
    $namaTopOnly = end($namaTopParts);
    $waktuMulai = strtotime($header['waktu_mulai']);
    $waktuSelesai = $header['waktu_selesai'] ? strtotime($header['waktu_selesai']) : null;

    // Row 9
    $sheet->mergeCells("B9:H9"); $sheet->setCellValue('B9', 'MAIN PIC: ' . $namaTopOnly);
    $sheet->mergeCells("I9:Y9"); $sheet->setCellValue('I9', 'NO. MACHIN: ' . $header['no_mesin']);
    $sheet->mergeCells("Z9:AF9"); $sheet->setCellValue('Z9', 'DATE: ' . date('d/m/Y', $waktuMulai));

    // Row 10
    $sheet->mergeCells("B10:H11"); $sheet->setCellValue('B10', 'SUPPORT PIC: ' . ($header['support_pic'] ?? '-'));
    $sheet->getStyle('B10')->getAlignment()->setVertical('top');
    $sheet->mergeCells("I10:Y10"); $sheet->setCellValue('I10', 'MACHINE TYPE: ' . $header['type_mesin']);
    $sheet->mergeCells("Z10:AF10"); $sheet->setCellValue('Z10', 'START TIME: ' . date('H:i:s', $waktuMulai));

    // Row 11
    $sheet->mergeCells("I11:Y11"); $sheet->setCellValue('I11', 'SERIAL NUMBER: ' . ($header['serial_nomor'] ?? '-'));
    $sheet->mergeCells("Z11:AF11"); $sheet->setCellValue('Z11', 'FINISH TIME: ' . ($waktuSelesai ? date('H:i:s', $waktuSelesai) : '-'));

    $sheet->getStyle("B9:AF11")->applyFromArray($borderStyle);
    $sheet->getStyle("B9:AF11")->getFont()->setBold(true);

    // Headers (Preventive has STANDARD CHECK)
    $sheet->mergeCells("B12:C13"); $sheet->setCellValue('B12', 'NO');
    $sheet->mergeCells("D12:I13"); $sheet->setCellValue('D12', 'ITEM CHECK');
    $sheet->mergeCells("J12:O13"); $sheet->setCellValue('J12', 'POINT CHECK');
    $sheet->mergeCells("P12:W13"); $sheet->setCellValue('P12', 'STANDARD CHECK');
    $sheet->mergeCells("X12:Y13"); $sheet->setCellValue('X12', 'HASIL');
    $sheet->mergeCells("Z12:AF13"); $sheet->setCellValue('Z12', 'REMARK');
    $sheet->getStyle("B12:AF13")->getAlignment()->setHorizontal('center')->setVertical('center');
    $sheet->getStyle("B12:AF13")->getFont()->setBold(true);
    $sheet->getStyle("B12:AF13")->applyFromArray($borderStyle);

    $row = 14;
    $startRow = $row;
    foreach ($details as $d) {
        if (!empty($d['is_section_start'])) {
            $sheet->mergeCells("B{$row}:AF{$row}");
            $sheet->setCellValue("B{$row}", $d['dynamic_section_header'] ?? '');
            $sheet->getStyle("B{$row}:AF{$row}")->getFill()->setFillType(\PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID)->getStartColor()->setARGB('FFF2F2F2');
            $sheet->getStyle("B{$row}:AF{$row}")->getFont()->setBold(true);
            $sheet->getStyle("B{$row}:AF{$row}")->getAlignment()->setHorizontal('center');
            $sheet->getStyle("B{$row}:AF{$row}")->applyFromArray($borderStyle);
            $row++;
        }

        $sheet->mergeCells("B{$row}:C{$row}");
        $sheet->setCellValue("B{$row}", $d['dynamic_no'] ?? '');

        $sheet->mergeCells("D{$row}:I{$row}");
        $sheet->setCellValue("D{$row}", $d['bagian_check'] ?? '');

        $sheet->mergeCells("J{$row}:O{$row}");
        $sheet->setCellValue("J{$row}", $d['point_check'] ?? '');

        $sheet->mergeCells("P{$row}:W{$row}");
        $sheet->setCellValue("P{$row}", $d['standard_check'] ?? '');
        $sheet->getStyle("P{$row}:W{$row}")->getAlignment()->setWrapText(true);

        $sheet->mergeCells("X{$row}:Y{$row}");
        $sheet->setCellValue("X{$row}", $d['hasil_check'] ?? '');
        $hasil = $d['hasil_check'] ?? '';
        if ($hasil === 'V') $sheet->getStyle("X{$row}")->getFont()->getColor()->setARGB('FF008000');
        elseif ($hasil === 'Δ') $sheet->getStyle("X{$row}")->getFont()->getColor()->setARGB('FFB8860B');
        elseif ($hasil === 'X') $sheet->getStyle("X{$row}")->getFont()->getColor()->setARGB('FFFF0000');
        $sheet->getStyle("X{$row}")->getFont()->setBold(true);
        $sheet->getStyle("X{$row}")->getAlignment()->setHorizontal('center');

        $sheet->mergeCells("Z{$row}:AF{$row}");

        // Insert Images
        $hasImage = false;
        $offsetX = 5;

        if (!empty($d['foto_abnormal'])) {
            $imgPath = FCPATH . 'uploads/abnormal/' . $d['foto_abnormal'];
            if (file_exists($imgPath)) {
                $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                $drawing->setName('Foto 1');
                $drawing->setPath($imgPath);
                $drawing->setCoordinates("Z{$row}");
                $drawing->setHeight(50);
                $drawing->setOffsetX($offsetX);
                $drawing->setOffsetY(5);
                $drawing->setWorksheet($sheet);
                $hasImage = true;
                $offsetX += 60;
            }
        }

        if (!empty($d['foto_abnormal_2'])) {
            $imgPath = FCPATH . 'uploads/abnormal/' . $d['foto_abnormal_2'];
            if (file_exists($imgPath)) {
                $drawing = new \PhpOffice\PhpSpreadsheet\Worksheet\Drawing();
                $drawing->setName('Foto 2');
                $drawing->setPath($imgPath);
                $drawing->setCoordinates("Z{$row}");
                $drawing->setHeight(50);
                $drawing->setOffsetX($offsetX);
                $drawing->setOffsetY(5);
                $drawing->setWorksheet($sheet);
                $hasImage = true;
            }
        }

        if ($hasImage) {
            $sheet->getRowDimension($row)->setRowHeight(60);
            $ulasanText = $d['ulasan'] ?? '';
            if (trim($ulasanText) !== '') {
                $sheet->setCellValue("Z{$row}", $ulasanText . "\n\n\n\n\n");
            }
        } else {
            $sheet->setCellValue("Z{$row}", $d['ulasan'] ?? '');
        }

        $sheet->getStyle("B{$row}:AF{$row}")->applyFromArray($borderStyle);
        $sheet->getStyle("B{$row}:AF{$row}")->getAlignment()->setVertical('center');
        $sheet->getStyle("B{$row}")->getAlignment()->setHorizontal('center');

        $row++;
    }

    $row++;
    // Note and Recommendation
    $sheet->mergeCells("B{$row}:AF{$row}");
    $sheet->setCellValue("B{$row}", "NOTE AND RECOMMENDATION");
    $sheet->getStyle("B{$row}:AF{$row}")->applyFromArray($borderStyle);
    $row++;
    $sheet->mergeCells("B{$row}:AF{$row}");
    $sheet->setCellValue("B{$row}", $header['note_recommendation'] ?? '');
    $sheet->getStyle("B{$row}:AF{$row}")->applyFromArray($borderStyle);
    $row++;
    $sheet->mergeCells("B{$row}:AF{$row}");
    $sheet->getStyle("B{$row}:AF{$row}")->applyFromArray($borderStyle);

    $row += 2;

    // Keterangan & Signature (Row 69 to 74 pattern)
    $sheet->mergeCells("B{$row}:I{$row}");
    $sheet->setCellValue("B{$row}", "KETERANGAN CHECK LIST");
    $sheet->getStyle("B{$row}:I{$row}")->getAlignment()->setHorizontal('center')->setBold(true);
    $sheet->getStyle("B{$row}:I{$row}")->applyFromArray($borderStyle);

    $sheet->mergeCells("M{$row}:R{$row}"); $sheet->setCellValue("M{$row}", "DIBUAT OLEH");
    $sheet->mergeCells("U{$row}:Z{$row}"); $sheet->setCellValue("U{$row}", "DISETUJUI OLEH");
    $sheet->getStyle("M{$row}:Z{$row}")->getAlignment()->setHorizontal('center')->setBold(true);
    $sheet->getStyle("M{$row}:R{$row}")->applyFromArray($borderStyle);
    $sheet->getStyle("U{$row}:Z{$row}")->applyFromArray($borderStyle);

    $row++;

    $sheet->mergeCells("B{$row}:C{$row}"); $sheet->setCellValue("B{$row}", "V");
    $sheet->setCellValue("D{$row}", ":");
    $sheet->mergeCells("E{$row}:I{$row}"); $sheet->setCellValue("E{$row}", "OK");
    $sheet->getStyle("B{$row}:D{$row}")->getAlignment()->setHorizontal('center')->setBold(true);

    $sheet->mergeCells("M{$row}:R{$row}"); $sheet->setCellValue("M{$row}", "PIC");
    $sheet->mergeCells("U{$row}:Z{$row}"); $sheet->setCellValue("U{$row}", "PIC LINE");
    $sheet->getStyle("M{$row}:Z{$row}")->getAlignment()->setHorizontal('center')->setBold(true);
    $sheet->getStyle("M{$row}:R{$row}")->applyFromArray($borderStyle);
    $sheet->getStyle("U{$row}:Z{$row}")->applyFromArray($borderStyle);

    $row++;

    $sheet->mergeCells("B{$row}:C{$row}"); $sheet->setCellValue("B{$row}", "Δ");
    $sheet->setCellValue("D{$row}", ":");
    $sheet->mergeCells("E{$row}:I{$row}"); $sheet->setCellValue("E{$row}", "PERLU TINDAKAN");
    $sheet->getStyle("B{$row}:D{$row}")->getAlignment()->setHorizontal('center')->setBold(true);

    // Blank signature box
    $sheet->mergeCells("M{$row}:R" . ($row+1));
    $sheet->mergeCells("U{$row}:Z" . ($row+1));
    if ($header['waktu_selesai']) $sheet->setCellValue("M{$row}", "[ Selesai ]");
    if ($header['status'] === 'Approved') $sheet->setCellValue("U{$row}", "[ Disetujui ]");
    $sheet->getStyle("M{$row}:Z".($row+1))->getAlignment()->setHorizontal('center')->setVertical('center')->setWrapText(true);
    $sheet->getStyle("M{$row}:R".($row+1))->applyFromArray($borderStyle);
    $sheet->getStyle("U{$row}:Z".($row+1))->applyFromArray($borderStyle);

    $row++;

    $sheet->mergeCells("B{$row}:C{$row}"); $sheet->setCellValue("B{$row}", "X");
    $sheet->setCellValue("D{$row}", ":");
    $sheet->mergeCells("E{$row}:I{$row}"); $sheet->setCellValue("E{$row}", "TIDAK ADA");
    $sheet->getStyle("B{$row}:D{$row}")->getAlignment()->setHorizontal('center')->setBold(true);

    $sheet->getStyle("B".($row-2).":I{$row}")->applyFromArray($borderStyle);

    $row++;

    $sheet->mergeCells("M{$row}:R{$row}"); $sheet->setCellValue("M{$row}", strtoupper($namaTopOnly));
    $sheet->mergeCells("U{$row}:Z{$row}"); $sheet->setCellValue("U{$row}", strtoupper($header['approver_nama'] ?? '(...............)'));
    $sheet->getStyle("M{$row}:Z{$row}")->getAlignment()->setHorizontal('center')->setBold(true);
    $sheet->getStyle("M{$row}:R{$row}")->applyFromArray($borderStyle);
    $sheet->getStyle("U{$row}:Z{$row}")->applyFromArray($borderStyle);

    $writer = \PhpOffice\PhpSpreadsheet\IOFactory::createWriter($spreadsheet, 'Xlsx');
    header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    header('Content-Disposition: attachment; filename="' . $filename . '"');
    header('Cache-Control: max-age=0');
    $writer->save('php://output');
    exit();
}

